class BillingService { public: virtual ~BillingService() = default;
    virtual Charge charge(const ChargeRequest&) = 0; };
class BillingDelegate : public BillingService {
  std::unique_ptr<Transport> transport_;          // transport hidden here
  std::optional<SessionHandle> handle_;           // cached lookup result
public:
  Charge charge(const ChargeRequest& r) override {
    if (!handle_) handle_ = lookup_.resolve("billing");
    try { return transport_->call(*handle_, r); }
    catch (const TransportError& e) { handle_.reset(); throw ServiceUnavailable{e.what()}; }
  }
